// Validate incoming job payload
const body = $input.item.json.body || $input.item.json;
if (!body.job_id || !body.video_id) {
  throw new Error('Invalid start payload: job_id and video_id are required');
}

return {
  json: {
    job_id: body.job_id,
    video_id: body.video_id,
    request: body.request || {},
    version: body.version || '1.0',
    received_at: new Date().toISOString()
  }
};

const input = $input.item.json;
const req = input.request || {};

// Generate Creative Brief (VF-01)
const brief = {
  workingTitle: req.title || 'فيديو ذكي - ' + (req.prompt ? req.prompt.substring(0, 30) : 'جديد'),
  coreIdea: req.prompt || '',
  objective: 'إنتاج محتوى فيديو احترافي على ' + (req.platform || 'tiktok'),
  targetAudience: 'جمهور منصات التواصل الرقمي المهتم بالمحتوى المبتكر',
  platform: req.platform || 'tiktok',
  videoType: req.type || 'short',
  targetDurationSeconds: req.duration_seconds || 30,
  language: req.language || 'ar',
  tone: 'حماسي واحترافي',
  contentAngle: 'طرح مباشر وسريع',
  hookStrategy: 'سؤال صادم أو معلومة مفاجئة في أول 3 ثوان',
  narrativeStyle: 'مشكلة -> حل -> دعوة للتفاعل',
  visualDirection: 'لقطات سينمائية مع موشن جرافيك توضيحي',
  pacing: 'fast',
  keyPoints: ['الوضوح', 'السرعة', 'التأثير'],
  constraints: ['الالتزام بالمدة المحددة'],
  requiresResearch: false
};

return {
  json: {
    ...input,
    brief: brief
  }
};

const input = $input.item.json;
const brief = input.brief || {};
const duration = brief.targetDurationSeconds || 30;

// Generate Script (VF-02)
const script = {
  videoId: input.video_id,
  title: brief.workingTitle,
  hook: brief.hookStrategy,
  fullNarration: 'هل تعلم أن المحتوى المرئي يجذب أكثر من 80% من تفاعل الجمهور؟ إليك الخطوات الأساسية لتحقيق أعلى وصول وتأثير في وقت قياسي. أولاً: اختر الفكرة المباشرة. ثانياً: ركز على الجودة البصرية. ثالثاً: شجع المشاهدين على المشاركة.',
  estimatedWordCount: Math.round(duration * 2.2),
  estimatedDurationSeconds: duration,
  language: brief.language || 'ar',
  callToAction: 'تابعنا للمزيد من المحتوى المميز',
  sections: [
    {
      id: 'sec_1',
      title: 'المقدمة والخطاف',
      narration: 'هل تعلم أن المحتوى المرئي يجذب أكثر من 80% من تفاعل الجمهور؟',
      targetDurationSeconds: Math.round(duration * 0.25)
    },
    {
      id: 'sec_2',
      title: 'الشرح والنقاط الأساسية',
      narration: 'إليك الخطوات الأساسية: اختر الفكرة المباشرة، وركز على الجودة البصرية.',
      targetDurationSeconds: Math.round(duration * 0.5)
    },
    {
      id: 'sec_3',
      title: 'الخاتمة والدعوة للإجراء',
      narration: 'شجع المشاهدين على المشاركة وتابعنا للمزيد!',
      targetDurationSeconds: Math.round(duration * 0.25)
    }
  ]
};

return {
  json: {
    ...input,
    script: script
  }
};

const input = $input.item.json;
const brief = input.brief || {};
const script = input.script || {};
const totalDur = brief.targetDurationSeconds || 30;

// Generate Scenes (VF-03)
const scenes = [
  {
    position: 1,
    purpose: 'Hook',
    narration: script.hook,
    onScreenText: brief.workingTitle,
    visualDescription: 'لقطة افتتاحية مشوقة بدقة سينمائية عالية',
    visualPrompt: 'Cinematic wide shot, dramatic studio lighting, 8k quality, engaging hero visual',
    mediaStrategy: 'AI_VIDEO',
    durationSeconds: Math.max(3, Math.round(totalDur * 0.25))
  },
  {
    position: 2,
    purpose: 'Explanation',
    narration: 'شرح الخطوات والنقاط الرئيسية',
    onScreenText: '3 خطوات للنجاح',
    visualDescription: 'رسوم بيانية وموشن جرافيك ثلاثي الأبعاد جذاب',
    visualPrompt: 'Dynamic 3D motion graphics isometric layout, neon glowing highlights, dark backdrop',
    mediaStrategy: 'MOTION_GRAPHICS',
    durationSeconds: Math.max(4, Math.round(totalDur * 0.5))
  },
  {
    position: 3,
    purpose: 'CTA Outro',
    narration: script.callToAction || 'تابعنا للمزيد',
    onScreenText: 'اشترك الآن',
    visualDescription: 'لقطة نهائية راقية تبرز زر المتابعة والتفاعل',
    visualPrompt: 'Minimalist aesthetic outro frame, soft ambient glow, professional finish',
    mediaStrategy: 'AI_IMAGE',
    durationSeconds: Math.max(3, totalDur - Math.round(totalDur * 0.25) - Math.round(totalDur * 0.5))
  }
];

return {
  json: {
    ...input,
    scenes: scenes
  }
};
